    @Test
    fun inflatesGzipInAnyChunkSize() {
        for (chunk in listOf(1, 5, 11, 4096)) {
            var names = mutableListOf<String>()
            val parser = M3uParser { names.add(it.name) }
            val pipeline = TextPipeline(parser::feed)
            gz.toList().chunked(chunk).forEach { pipeline.feed(it.toByteArray()) }
            pipeline.finish()
            parser.finish()
            assertEquals(200, names.size, "chunk=$chunk")
            assertEquals("Ch 199", names.last())
        }
    }
